import fs from 'node:fs';

const OUT = process.argv[2];
const src = JSON.parse(fs.readFileSync('/Users/yuriiiz/Projects/Memories/.opc/phase1/success.json', 'utf8'));
const items = src.items.map(x => ({ ...x }));

const find = (frag) => {
  const i = items.findIndex(x => x.statement.includes(frag));
  if (i < 0) throw new Error('not found: ' + frag);
  return i;
};

// —— 改写 #2：平权，补上一直欠着的「视觉平权」
items[find('用户物件与内置 14 件平权')] = {
  statement: '用户物件与内置 14 件平权（能力＋视觉两条都算）：上传来的物件能拖入场景、挪位、缩放、旋转、写故事、重命名、跨场景摆放且故事同步——内置物件能做的它都能做；此外还能删除（内置 14 件不可删）。**视觉上同样平权：抠图后的用户物件以透明背景立在房间里，不再是一张贴着方块背景的照片。**',
  falsifiable_by: '逐项对一件上传物件施加内置物件的全部操作，任一项不可用或行为不一致；或上传物件删不掉；或内置物件出现了删除入口；**或用户选择了抠图版本入场后，该物件在场景中仍带着矩形照片背景（与内置透明物件明显不是一类东西）**，即判失败。'
};

// —— 改写 #4：存储压力因「原图＋抠图各存一份」进一步变大
items[find('存储失败必被告知')] = {
  statement: '存储失败必被告知，绝不静默丢数据：当写入失败（配额超限、隐私模式等）时界面出现明确提示，不出现「看起来存上了、刷新就没了」的情况。本轮存储压力进一步变大——背景按原图存，且每件用户物件要同时存原图与抠好的透明图两份——此条尤须成立。',
  falsifiable_by: '人为占满存储配额（或在隐私模式下）再上传一张照片或一张背景，若界面无任何提示、或提示成功但刷新后该物件/背景/抠图结果消失，即判失败。'
};

// —— 改写 #7：处理接口不再是恒等直通，但「可整体替换」这一架构性质保留
items[find('处理接口留在正确的位置')] = {
  statement: '处理接口接上了真实抠图，且仍可整体替换：物件管线仍为「规范化后的图 →【处理接口】→ 可入场景的图」，本轮该接口的默认实现由恒等直通换成真实的浏览器端抠图；架构性质不变——将来换别的模型或加风格化，仍只需替换这一层，上下游（解码降采样、宽高比测量、入库、存储、UI）一行不用改。',
  falsifiable_by: '写一个反例实现（例如把图转成灰度）塞进该接口，若不改上下游任何一行代码、上传出来的物件即变成灰度，则「可替换」成立；若为了让它生效必须改动管线上下游、存储或 UI，即判失败。另：若默认实现仍是恒等直通（上传出来的图与规范化后的图逐像素相同、无 alpha 通道），即判本轮失败。'
};

// —— 改写 #8：访客侧仍关得住，但主人必须有一扇看得见的门
items[find('游客模式关得住')] = {
  statement: '游客模式关得住，但主人有一扇看得见的门：切到游客模式后，看不到也用不到任何上传、删除、重命名入口，点物件只弹故事与原图（只读）；模式开关那组按钮仍不渲染。**但界面角落必须有一枚低调、找得到、点得到的「退出游客模式」小钮，主人一点即回编辑模式**——四版「界面上找得到任何切回编辑的按钮即判失败」这条口径本轮作废（其成因是把「主人」与「访客」混为一谈，而分享未做、远端访客尚不存在）。现有 ?edit URL 参数保留作兜底。',
  falsifiable_by: '在游客模式下找得到任一上传/删除/重命名入口、找得到模式开关那组按钮、或能改动任何数据，即判失败；**反过来，若在游客模式下找不到或点不到那枚退出小钮（不存在、被 pointer-events 挡掉、小到看不见、或点了没反应），同样判失败**。另：?edit 参数若失效，判失败。'
};

// —— 改写 #9：贴合实物的约束从内置素材扩大到用户抠图物件
items[find('内置素材贴合实物')] = {
  statement: '素材贴合实物（本轮适用范围由内置扩大到用户抠图物件）：items/ 下 14 张内置 PNG 与**用户上传后抠图入场的物件**，均须经 alpha 阈值裁切（烘焙软阴影不算实体）后，不透明像素包围盒到图片四边的距离 ≤8px，选中框贴合可见实物、比例不被阴影或抠图残留的透明区撑歪。',
  falsifiable_by: '脚本逐张测量 14 张内置物件 PNG 的透明边距，任一张任一边超过 8px；或**上传一张旧物照片、选抠图版本入场后，其选中框明显大于可见实物一圈**（透明边距超过 8px），即判失败。用户选择「用原图」入场的矩形照片与用户上传的背景不在此条适用范围内，不得据此判其失败。'
};

// —— 新增：抠图这件正事本身
const insertAfter = find('处理接口接上了真实抠图');
const added = [
  {
    statement: '抠图真的发生了，且照片不出本机：上传一张旧物照片后，管线在**浏览器本地**跑完抠图，产出一张背景透明的图；全过程不发生任何图片数据的网络外传（无第三方 API、无后端上传），模型文件作为本站静态资源加载。',
    falsifiable_by: '传一张照片并在浏览器 Network 面板全程观察：若出现任何把图片字节发往外部服务的请求，即判失败；或产出图不含 alpha 通道（逐像素采样 alpha 恒为 255）、与原图逐像素相同，即判抠图未发生、失败。'
  },
  {
    statement: '抠不准有退路：抠图完成后，预览弹窗里并排展示「抠好的」与「原图」两张，由用户点选哪一张入场；选原图时进场的就是不带透明通道的原始矩形照片，选抠图时进场的是抠好并裁过透明边的图。两条路都能走完入库、摆放、写故事全流程。',
    falsifiable_by: '上传一张照片后，若预览里只给一张图、没有二选一；或选了「原图」结果进场的仍是抠图版（反之亦然）；或二者之一入库后无法摆放/写故事，即判失败。'
  },
  {
    statement: '抠图按设备能力分两档且用户无感：有 WebGPU 的环境（桌面浏览器、iOS 26+）用高质量档，无 WebGPU 的环境（手机、老设备）自动降到轻量档（U-2-Netp，4.7MB）；模型按需懒加载——不上传图就不下载任何模型；下载与推理期间界面有明确的进行中状态或进度，不是一个没说明的转圈。',
    falsifiable_by: '在关闭 WebGPU 的环境里上传照片，若加载的是高质量档模型、或直接报错不可用（而非降档）；或首屏加载时即下载模型文件（未上传任何图）；或抠图耗时数秒期间界面无任何进行中反馈，即判失败。'
  },
  {
    statement: '抠图在 iPhone 上不崩：在横屏 iPhone 上传一张手机拍的旧物照片并走完抠图，页面不崩溃、标签页不被系统杀掉，抠图能在可忍受的时间内出结果。',
    falsifiable_by: '在真机 iPhone 上连续上传三张手机原图走抠图：若任一次页面崩溃、标签页被杀、或长时间无结果且无任何反馈，即判失败。'
  },
  {
    statement: '透明图用 WebP 落库、原图另存：抠好的透明图以 WebP（带 alpha 通道）落库，不用 JPEG（会丢透明度变黑底）也不用 PNG（体积过大）；原始照片另存一份，故事弹窗里点开看到的仍是用户拍的那张原图。',
    falsifiable_by: '检查落库的展示图 MIME/魔数：若为 image/jpeg（或产出图背景变黑），即判失败；或故事弹窗里显示的是抠好的透明图而非原始照片，即判失败。'
  }
];
items.splice(insertAfter + 1, 0, ...added);

fs.writeFileSync(OUT, JSON.stringify({ items }));
console.log('success items:', items.length, 'bytes:', fs.statSync(OUT).size);

