import fs from 'node:fs';

const OUT = process.argv[2];
const src = JSON.parse(fs.readFileSync('/Users/yuriiiz/Projects/Memories/.opc/phase1/milestones.json', 'utf8'));

// 只留里程碑本体字段——status / claimed_at_tick / needs_fix / verdicts / fail_count 一个字都不许抄回来
const KEEP = ['id', 'artifact_required', 'review_required', 'goal', 'criteria'];
const strip = (m) => {
  const out = {};
  for (const k of KEEP) if (m[k] !== undefined) out[k] = m[k];
  return out;
};

const list = src.map(strip);
const at = (id) => {
  const i = list.findIndex(x => x.id === id);
  if (i < 0) throw new Error('missing ' + id);
  return i;
};

const build = (cmd, timeout = 240000) => ({
  type: 'command',
  cmd: ['npx', 'playwright', 'test', cmd, '--reporter=line'],
  expect_exit: 0,
  timeout_ms: timeout
});
const buildProd = {
  type: 'command',
  cmd: ['npm', 'run', 'build'],
  expect_exit: 0,
  timeout_ms: 180000
};

// ——————————————————————————————————————————————
// P1 · 主人的门（游客模式可逆化）
// ——————————————————————————————————————————————
const P1 = {
  id: 'P1',
  artifact_required: true,
  goal: '主人的门（游客模式可逆化）：四版 E1-S2 为堵「访客能点编辑」这个洞，把模式开关整组从 DOM 拿掉（Header.tsx:76），只留 App.tsx:24-36 的 ?edit URL 后门。后门功能上无 bug，但只写在源码注释与 receipt 里、产品界面零提示，而 guest 又随整棵状态树落盘（persistence.ts:197），刷新重开都还是游客——老板作为这条逃生门的指定使用者被自己的应用锁在了门外。本里程碑在游客模式下于界面角落渲染一枚低调的「退出游客模式」小钮（半透明毛玻璃、符合旧信·沉浸规范与 token 字号下限、不抢戏、不遮挡场景主体），点击即 dispatch set-mode 回编辑模式并落盘；现有 ?edit 参数保留不动作为兜底。除这枚小钮外，游客模式仍不渲染模式开关那组按钮，以及任何上传/删除/重命名入口。**本轮放开是因为分享尚未做、远端访客根本不存在，不是因为访客侧该放开——分享落地那一轮必须把这枚小钮在访客那一份里关掉，此约束已记入 idea 的否决/约束清单。**工程可生产构建。',
  criteria: [
    {
      desc: '主人的门存在且真能回去：游客模式下界面上找得到并点得到「退出游客模式」小钮（真实可见、未被 pointer-events 挡掉、命中区不小于可点尺寸），点击后立即回到编辑模式——模式开关那组按钮重新出现、上传/删除/重命名入口重新可用；刷新后仍停在编辑模式（已落盘）。',
      check: build('e2e/p1-owner-door.spec.ts')
    },
    {
      desc: '访客侧仍关得住：游客模式下除那枚退出小钮外，找不到模式开关那组按钮（mode-edit/mode-guest 在 DOM 中计数为 0），也找不到任何上传、删除、重命名入口；点物件只弹故事与原图，改不动任何数据。既有的 ?edit URL 参数仍然可用（作为兜底路径未被回归破坏）。',
      check: build('e2e/p1-guest-locked.spec.ts')
    },
    {
      desc: '【人工·老板亲验】小钮低调不抢戏：这枚退出小钮落在既有「旧信 · 沉浸」规范内——半透明毛玻璃、陶土红为唯一强调、字号不低于 token 下限、不遮挡场景主体、正常浏览时不抢戏，但老板一眼能找到。沿用四版「效果类由老板亲验」的定调。',
      manual: true
    },
    {
      desc: '生产构建通过：Vite 生产构建成功、无类型错误。',
      check: buildProd
    }
  ]
};

// ——————————————————————————————————————————————
// P2 · 抠图入场
// ——————————————————————————————————————————————
const P2 = {
  id: 'P2',
  artifact_required: true,
  goal: '抠图入场（用户物件与内置素材真正平权）：把 src/upload/processor.ts:42 的 defaultProcessor 槽从 identityProcessor（原样返回的空壳，全项目生产代码无一处调用 setImageProcessor，运行时 100% 直通）换成真实的浏览器端抠图实现。要点：(1) 新增唯一运行时依赖 onnxruntime-web（MIT），模型作为本站静态资源自托管，零后端、零 API key、图片零字节外传——「照片不出本机」不但不破、反而被再次确认；明确绕开 transformers.js（其 iOS Safari 崩溃 issue #1242 自 2025-03 未见修复证据）。(2) 按设备能力分两档且用户无感：启动时探一次 WebGPU 可用性，有则用高质量档 BiRefNet（MIT），无则降到轻量档 U-2-Netp（4.7MB，Apache-2.0，WASM 后端）；人像专用的 MODNet 已因「只做人像、对无生命物体表现差」出局。(3) 模型按需懒加载——不上传图就不下载任何模型，不拖慢首屏；下载与推理期间给明确的进行中状态或进度。(4) 抠不准有退路：抠完在预览弹窗里并排展示「抠好的」与「原图」，由用户点选哪张入场。(5) 透明图存 WebP 而非 JPEG（JPEG 不支持 alpha，透明度会在 normalize.ts:67 的编码环节丢失变黑底）也不用 PNG（体积是 JPEG 的 3–5 倍，叠加双份存储会顶爆配额）。(6) 抠完必须裁透明边：把 scripts/lib/trim.mjs 的 alpha 阈值裁边逻辑（ALPHA_SOLID=240、边距 ≤8px，原为内置素材写的离线脚本）搬到运行时对用户物件也跑一遍，否则选中框会比实物大一圈。(7) types.ts:41 早已预留的 originalImageSrc 与 displayImageSrc 两个图位各就各位：抠好的透明图入场景，原始照片留给故事弹窗——这补上四版「用户物件与内置 14 件平权」一直未兑现的视觉那一半。工程可生产构建。',
  criteria: [
    {
      desc: '抠图真的发生了、且照片零外传：上传一张旧物照片走完管线后，落库的展示图带 alpha 通道（存在 alpha<255 的像素）且与规范化后的原图不逐像素相同；全程无任何把图片字节发往外部服务的网络请求（模型文件除外，且模型来自本站同源静态资源）。',
      check: build('e2e/p2-cutout-happens.spec.ts')
    },
    {
      desc: '产出格式与裁边：落库的展示图为 image/webp 且带 alpha（不是 jpeg、不是不透明图）；对该展示图逐边测量不透明像素包围盒，四边透明边距均 ≤8px（与内置素材同一把尺子）；原始照片另存一份，故事弹窗里展示的是原图而非抠图。',
      check: build('e2e/p2-webp-trim.spec.ts')
    },
    {
      desc: '二选一有退路：抠图完成后预览弹窗里并排给出「抠好的」与「原图」两个选项且都能点；选「原图」入场的是不带 alpha 的原始矩形照片，选「抠好的」入场的是带 alpha 且已裁边的图；两条路都能走完入库、拖进场景、写故事、刷新后仍在。',
      check: build('e2e/p2-choice.spec.ts')
    },
    {
      desc: '分档与懒加载：未上传任何图时首屏不下载模型文件（Network 中无模型请求）；WebGPU 不可用的环境下自动降到轻量档而非报错不可用；抠图进行期间界面有明确的进行中状态或进度反馈（不是一个没说明的转圈）。既有的「处理接口可整体替换」性质不回归——注入灰度反例处理器仍能仅换一层即改变产出。',
      check: build('e2e/p2-tier-lazy.spec.ts')
    },
    {
      desc: '【人工·老板亲验】效果与真机：老板拿自己的旧物照片，在 PC 与自己的 iPhone 上各传几张走完抠图——抠出来的东西可接受（能立在房间里像件物件，而不是一坨残渣）、耗时可忍、iPhone 上页面不崩溃、标签页不被系统杀掉；抠得不好时用「原图」那条退路能顺利绕过。沿用四版「效果类由老板亲验」的定调。',
      manual: true
    },
    {
      desc: '生产构建通过：Vite 生产构建成功、无类型错误。',
      check: buildProd
    }
  ]
};

// 插队：紧跟在 E1（游客门所在的那块）之后、E2 之前
list.splice(at('E1') + 1, 0, P1, P2);

// ——————————————————————————————————————————————
// E5 收口：范围扩大，作废「不抠图」护栏
// ——————————————————————————————————————————————
const e5 = list[at('E5')];
e5.goal = '收口·全流程 ＋ 双端达标：覆盖全部成功条件的端到端全流程（传背景建场景 → 传照片并在抠图预览里二选一 → 摆物件 → 写故事 → 撤销一次 → 切游客看故事 → 点角落小钮回编辑）在 PC 与横屏手机都跑通、布局不错乱；前四代 M1~M4 / N1~N4 / U1~U4 / E1 与 P1、P2 的 e2e 全部不回归；无 console 未捕获错误、无横向溢出；整体仍还原「旧信 · 沉浸」DNA。';
e5.criteria = [
  {
    desc: '全流程双端 e2e：传背景建场景 → 传照片并在抠图预览里二选一 → 摆物件 → 写故事 → 撤销一次 → 切游客看故事 → 点角落小钮回编辑，在 PC 与横屏手机视口下均跑通、布局不错乱；过程中无 console 未捕获错误、无横向滚动条。',
    check: build('e2e/e5-full.spec.ts')
  },
  {
    desc: '旧里程碑不回归：M1~M4、N1~N4、U1~U4、E1~E4 与 P1、P2 的既有 e2e 全套跑通（全量 playwright 套件绿）。',
    check: {
      type: 'command',
      cmd: ['npx', 'playwright', 'test', '--reporter=line'],
      expect_exit: 0,
      timeout_ms: 900000
    }
  },
  {
    desc: '【人工·老板亲验】整体仍还原「旧信 · 沉浸」DNA：本轮新增的退出游客小钮、抠图预览的二选一版面、抠图进行中的进度反馈，以及四版的撤销提示条、层次/归正工具、背景上传入口与背景库、各类反馈文案，均落在既有规范内（毛玻璃浮层、奶油半透明弹窗、陶土红唯一强调、UI 字号不低于 token 下限、不对称控件做视觉居中补偿）。【判定护栏】四版「用户上传的照片仍按裸矩形原图入场（不抠图）……不得据此判失败」一句**本轮作废**——抠图已是本轮正事。仍然有效的护栏：用户主动选择「用原图」入场时该物件保持裸矩形，不得据此判失败；用户上传的背景仍按原图不压缩入场，亦不得据此判失败；「装裱/风格化」仍不在本轮范围内。',
    manual: true
  }
];

fs.writeFileSync(OUT, JSON.stringify(list));
console.log('milestones:', list.map(x => x.id).join(' '), '| bytes:', fs.statSync(OUT).size);

